/**
 * The endpoint ledger of the checked browser JSON boundary (P114; moved into the core by P119 so that no core test reads
 * the plan repo). Every `operationId` of `openapi.yaml` is listed under its domain, generated by Orval, exported by the
 * public `@hub/api` barrel and consumed by one admin domain facade. Every path an admin facade still calls raw is listed
 * under the reason it stays raw: it carries a credential, a lifecycle protocol, a local bridge, a stream or keepalive, or
 * the owner-confirmed send door. A raw family is never promoted to an agent tool or a generic mutation.
 *
 * Adding a browser JSON endpoint: add its OpenAPI operation, generate, export it from `src/index.ts`, move the facade to
 * `readGenerated`, and list the operation here. An endpoint that stays raw on purpose: list its path here under its reason.
 * `apps/admin/test/rules.test.ts` fails when the spec, the barrel and this ledger disagree, or when a raw facade path has
 * no family here.
 */
export const GENERATED_OPERATIONS = {
  instance: ["getInstance", "getCoreUpdate", "getAutostart", "listConnections", "listProjects", "getOverview", "getPulse", "getProjectOverview", "getProjectDoctor", "getProjectLinks", "getScheme", "getOpsErrors", "getAgentSettings", "getSafetyRules", "getActivity", "getAgentTools", "getAgentFeed"],
  mail: ["listDrafts", "listBatches", "listNotByEmail", "listInbound", "getInboundDetail", "getInboundText", "listEnrollments", "stopEnrollment", "getLeadDetail", "listSequences", "getClientTimeline", "getClientHistory", "listKnowledge", "listConversations", "getConversation", "getConversationMail", "getConversationText", "getDraftMail", "setClientMarks", "createManualMailDraft", "listSends"],
  /** Messenger reads and unsent-draft writes only; the delivery is the send door below. */
  messengers: ["getTelegramUserStatus", "getWhatsAppStatus", "listMessengerChats", "getMessengerConversation", "createMessengerDraft", "editMessengerDraft", "skipMessengerDraft", "restoreMessengerDraft", "prepareMessengerReply", "setMessengerChatRules"],
} as const;

export const RAW_PATHS = {
  /** Credential and lifecycle protocols, local bridges and streams. */
  protocols: ["/api/connections", "/api/instance", "/api/messengers/telegram-user", "/api/messengers/whatsapp", "/api/terminal", "/api/focus", "/api/pointer", "/api/projects/:slug/agent-tools", "/api/safety-rules", "/api/agent-settings", "/api/local"],
  /** The Mail draft and send doors. */
  mailDoors: ["/api/drafts", "/api/batches", "/api/projects/:slug/drafts/:id/mail", "/api/projects/:slug/drafts/:id/mail/restore", "/api/projects/:slug/drafts/:id/send", "/api/projects/:slug/batches/:id/send", "/api/projects/:slug/batches/:id/send/stop", "/api/sends", "/api/sends/tickets", "/api/sends/batch-tickets"],
  /** The owner-gated Messenger identity writes (autolink, chat management) and the Messenger send door. */
  messengerDoors: ["/api/projects/:slug/messengers/autolink/*", "/api/projects/:slug/messengers/chats/*", "/api/projects/:slug/messengers/drafts/:id/send"],
} as const;

export type GeneratedOperation = (typeof GENERATED_OPERATIONS)[keyof typeof GENERATED_OPERATIONS][number];
export type RawPath = (typeof RAW_PATHS)[keyof typeof RAW_PATHS][number];

export const generatedOperations = (): readonly GeneratedOperation[] => Object.values(GENERATED_OPERATIONS).flat();
export const rawPaths = (): readonly RawPath[] => Object.values(RAW_PATHS).flat();
/** The family of an API path: its first two segments (`/api/projects/:slug/...` is `/api/projects`). */
export const apiFamily = (path: string): string => path.split("/").slice(0, 3).join("/");
